WITH base AS (SELECT id, session_id, page, event_time, duration_sec, HOUR(event_time) AS event_time_hour FROM web_events WHERE page IS NOT NULL AND event_time >= TIMESTAMP '2023-07-29 22:00:00') SELECT CASE WHEN duration_sec >= 444 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, SORT_ARRAY(COLLECT_SET(page)) AS page_list, AVG(event_time_hour) FILTER (WHERE page = '/search') AS search_avg_event_time_hour, (UNIX_TIMESTAMP(MAX(event_time)) - UNIX_TIMESTAMP(MIN(event_time))) / 60 AS duration_min FROM base GROUP BY CASE WHEN duration_sec >= 444 THEN 'LARGE' ELSE 'SMALL' END;
